import { MakeLogicType, actions, kea, key, listeners, path, props, reducers, selectors } from 'kea'
import posthog from 'posthog-js'

/**
 * Where a notebook's Python and DuckDB cells run. 'browser' runs them in this tab with Pyodide;
 * 'sandbox' runs them on PostHog compute. SQL that only reads PostHog data runs in ClickHouse
 * either way.
 */
export type NotebookKernelProvider = 'browser' | 'sandbox'

export type NotebookKernelProviderLogicProps = {
    shortId: string
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface notebookKernelProviderLogicValues {
    isBrowserKernel: boolean
    provider: NotebookKernelProvider
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface notebookKernelProviderLogicActions {
    setProvider: (provider: NotebookKernelProvider) => {
        provider: NotebookKernelProvider
    }
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface notebookKernelProviderLogicMeta {
    key: string
    __keaTypeGenInternalSelectorTypes: {
        isBrowserKernel: (provider: NotebookKernelProvider) => boolean
    }
}

export type notebookKernelProviderLogicType = MakeLogicType<
    notebookKernelProviderLogicValues,
    notebookKernelProviderLogicActions,
    NotebookKernelProviderLogicProps,
    notebookKernelProviderLogicMeta
>

// The choice is per person and per notebook, and kept in this browser: a browser kernel only ever
// runs in the tab of whoever picked it, so a collaborator's choice must not change where yours runs.
export const notebookKernelProviderLogic = kea<notebookKernelProviderLogicType>([
    path((key) => ['scenes', 'notebooks', 'Notebook', 'browserKernel', 'notebookKernelProviderLogic', key]),
    props({} as NotebookKernelProviderLogicProps),
    key((props) => props.shortId),
    actions({
        setProvider: (provider: NotebookKernelProvider) => ({ provider }),
    }),
    reducers({
        provider: [
            'browser' as NotebookKernelProvider,
            { persist: true },
            {
                setProvider: (_, { provider }) => provider,
            },
        ],
    }),
    listeners(({ props }) => ({
        setProvider: ({ provider }) => {
            posthog.capture('notebook kernel provider changed', { provider, notebook_short_id: props.shortId })
        },
    })),
    selectors({
        isBrowserKernel: [(s) => [s.provider], (provider: NotebookKernelProvider): boolean => provider === 'browser'],
    }),
])
